INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7036351, 1069215, 43463, '<td valign="top">Don''t know how to vote on this one at the moment (though I am very much a Stars Wars Fan and find this well done). I find my time is occupied more with the mechanics of the shot in that I am trying to figure out how you managed to pull it off in Advanced. Hmmm. O.k. perspective and angle is working for you here on this one. My best educated guess is that there is a contraption hidden behind the box &amp; in the field; a platform that allows Vader to sit in that box making it look like it is floating above the fields. I''d go further in that the cardboard box is attached to that seat platform but maybe a few inches below it so that it can more effectively hide the contraption that allows Vader to paddle in the box. Angle helps to hide and give this illusion:-)</td>', 'Don''t know how to vote on this one at the moment (though I am very much a Stars Wars Fan and find this well done). I find my time is occupied more with the mechanics of the shot in that I am trying to figure out how you managed to pull it off in Advanced. Hmmm. O.k. perspective and angle is working for you here on this one. My best educated guess is that there is a contraption hidden behind the box & in the field; a platform that allows Vader to sit in that box making it look like it is floating above the fields. I''d go further in that the cardboard box is attached to that seat platform but maybe a few inches below it so that it can more effectively hide the contraption that allows Vader to paddle in the box. Angle helps to hide and give this illusion:-)', '2013-05-13 01:23:54.000000', NULL, 1),
